"use client";

import { ApiHealth } from "@/components/api-health";
import { ApiError, apiFetch } from "@/lib/api";
import type { FormEvent, ReactNode } from "react";
import { useEffect, useMemo, useState } from "react";

type UserRole = "Admin" | "Manager" | "BuildingStaff";
type PropertyType = "ApartmentBuilding" | "IndividualRoomBuilding" | "Shop";
type OccupancyStatus = "Unknown" | "Occupied" | "Vacant";
type ChargeType = "Electricity" | "Water" | "Gas" | "ServiceCharge" | "Rent" | "Custom";
type ChargeSettingMode = "Inherited" | "Custom" | "Disabled";
type BillingCycleStatus = "Draft" | "Submitted" | "Returned" | "Approved";
type MeterReadingSource = "Missing" | "ApprovedPeriod" | "OpeningEntry";
type BillingAuditAction = "Generated" | "Saved" | "Submitted" | "Returned" | "Approved";

type User = { id: string; email: string; fullName: string; role: UserRole; organizationId: string };
type Organization = { id: string; name: string };
type Session = { user: User; organization: Organization };
type Unit = { id: string; name: string; isEnabled: boolean; isArchived: boolean; occupancyStatus: OccupancyStatus };
type Floor = { id: string; name: string; sortOrder: number; isArchived: boolean; units: Unit[] };
type Property = { id: string; name: string; address: string; propertyType: PropertyType; isArchived: boolean; floors: Floor[] };
type Tenant = { id: string; name: string | null; phone: string | null; onboardingStatus: "NotConnected" };
type StaffMember = { user: User; propertyIds: string[] };
type FloorDraft = { name: string; unitCount: number; unitNames: string };
type PropertyPreview = { floors: { name: string; sortOrder: number; units: { name: string; sortOrder: number }[] }[] };
type ChargeConfiguration = { id: string; unitId: string | null; chargeType: ChargeType; mode: ChargeSettingMode; billingMonth: string; amount: number | null; customLabel: string | null };
type ChargeDraft = { key: string; chargeType: ChargeType; mode: ChargeSettingMode; billingMonth: string; amount: string; customLabel: string };
type OccupancyRecord = { id: string; tenantId: string; name: string | null; phone: string | null; startDate: string; endDate: string | null };
type BillingChargeLine = { id: string; chargeType: ChargeType; chargeName: string; settingMode: ChargeSettingMode; isMetered: boolean; rate: number | null; previousReading: number | null; currentReading: number | null; consumptionUnits: number | null; previousReadingSource: MeterReadingSource; amount: number };
type BillingUnitBill = { id: string; unitId: string; unitName: string; occupancyAssignmentId: string | null; tenantId: string | null; tenantName: string | null; tenantPhone: string | null; occupancyStartDate: string | null; occupancyEndDate: string | null; blockingReason: string | null; total: number; electricityWarning: boolean; charges: BillingChargeLine[] };
type BillingAudit = { id: string; actorUserId: string; action: BillingAuditAction; occurredAtUtc: string; reason: string | null; before: string | null; after: string | null };
type BillingCycle = { id: string; propertyId: string; billingMonth: string; status: BillingCycleStatus; version: number; lastChangedByUserId: string; lastChangedAtUtc: string; returnReason: string | null; draftTotal: number; approvedTotal: number | null; blockingBillCount: number; bills: BillingUnitBill[]; audit: BillingAudit[] };

const propertyTypeLabels: Record<PropertyType, string> = { ApartmentBuilding: "Apartment building", IndividualRoomBuilding: "Individual-room building", Shop: "Shops" };
const roleLabels: Record<UserRole, string> = { Admin: "Admin", Manager: "Manager", BuildingStaff: "Building staff" };
const chargeTypeLabels: Record<ChargeType, string> = { Electricity: "Electricity", Water: "Water", Gas: "Gas", ServiceCharge: "Service charge", Rent: "Rent", Custom: "Custom" };
const chargeTypes: ChargeType[] = ["Electricity", "Water", "Gas", "ServiceCharge", "Rent", "Custom"];
const initialFloors: FloorDraft[] = [
  { name: "Floor 1", unitCount: 2, unitNames: "1A, 1B" },
  { name: "Floor 2", unitCount: 2, unitNames: "2A, 2B" },
  { name: "Floor 3", unitCount: 2, unitNames: "3A, 3B" },
  { name: "Floor 4", unitCount: 1, unitNames: "4A" },
];

export function DashboardWorkspace() {
  const [session, setSession] = useState<Session | null>(null);
  const [loading, setLoading] = useState(true);
  const [mode, setMode] = useState<"login" | "register" | "accept">("login");
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");

  useEffect(() => { apiFetch<Session>("/api/auth/me").then(setSession).catch(() => setSession(null)).finally(() => setLoading(false)); }, []);
  if (loading) return <CenteredState label="Loading your PrimeTect workspace…" />;
  if (!session) return <AuthScreen mode={mode} onModeChange={setMode} onAuthenticated={(next) => { setError(""); setMessage(""); setSession(next); }} onError={setError} />;
  return <Workspace session={session} message={message} error={error} onMessage={setMessage} onError={setError} onLogout={async () => { await apiFetch<void>("/api/auth/logout", { method: "POST" }); setSession(null); setMode("login"); }} />;
}

function AuthScreen({ mode, onModeChange, onAuthenticated, onError }: { mode: "login" | "register" | "accept"; onModeChange: (mode: "login" | "register" | "accept") => void; onAuthenticated: (session: Session) => void; onError: (message: string) => void }) {
  const [form, setForm] = useState({ organizationName: "", fullName: "", email: "", password: "", token: "" });
  const [busy, setBusy] = useState(false);
  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); onError(""); setBusy(true);
    try {
      if (mode === "login") await apiFetch<User>("/api/auth/login", { method: "POST", body: JSON.stringify({ email: form.email, password: form.password }) });
      else if (mode === "register") await apiFetch("/api/auth/register-owner", { method: "POST", body: JSON.stringify({ organizationName: form.organizationName, fullName: form.fullName, email: form.email, password: form.password }) });
      else await apiFetch("/api/auth/accept-invitation", { method: "POST", body: JSON.stringify({ token: form.token, fullName: form.fullName, password: form.password }) });
      onAuthenticated(await apiFetch<Session>("/api/auth/me"));
    } catch (caught) { onError(getErrorMessage(caught, "We could not complete that request.")); } finally { setBusy(false); }
  }
  return <main className="min-h-screen bg-sand px-6 py-8 sm:px-10 lg:px-14"><div className="mx-auto grid min-h-[calc(100vh-4rem)] max-w-6xl items-center gap-12 lg:grid-cols-[1fr_0.8fr]"><div><BrandMark /><p className="mt-14 text-xs font-bold uppercase tracking-[0.28em] text-pine">Property operations, made clear</p><h1 className="mt-5 max-w-xl text-5xl font-black leading-[0.98] tracking-[-0.07em] text-ink sm:text-7xl">A better day for every property team.</h1><p className="mt-7 max-w-lg text-lg leading-8 text-ink/60">Start with a secure workspace for your organization, then shape every building floor by floor.</p></div><form onSubmit={submit} className="rounded-[2rem] border border-ink/10 bg-white/80 p-7 shadow-soft sm:p-9"><div className="flex flex-wrap gap-5 border-b border-ink/10 text-sm font-bold"><AuthTab active={mode === "login"} onClick={() => onModeChange("login")}>Log in</AuthTab><AuthTab active={mode === "register"} onClick={() => onModeChange("register")}>Set up workspace</AuthTab><AuthTab active={mode === "accept"} onClick={() => onModeChange("accept")}>Accept invitation</AuthTab></div><h2 className="mt-8 text-2xl font-black tracking-[-0.05em] text-ink">{mode === "login" ? "Welcome back" : mode === "register" ? "Create your organization" : "Join your organization"}</h2><p className="mt-2 text-sm leading-6 text-ink/55">{mode === "login" ? "Use your PrimeTect account to continue." : mode === "register" ? "This creates the organization and its first Admin account together." : "Paste the one-time token shared manually by your Admin. No invitation email is sent in this milestone."}</p>{mode === "register" && <Field label="Organization name" value={form.organizationName} onChange={(value) => setForm({ ...form, organizationName: value })} placeholder="Northstar Property Group" required />}{mode !== "login" && <Field label="Your full name" value={form.fullName} onChange={(value) => setForm({ ...form, fullName: value })} placeholder="Amina Rahman" required />}{mode !== "accept" && <Field label="Email" type="email" value={form.email} onChange={(value) => setForm({ ...form, email: value })} placeholder="you@example.com" required />}{mode === "accept" && <Field label="Invitation token" value={form.token} onChange={(value) => setForm({ ...form, token: value })} placeholder="Paste the secure one-time token" required />}<Field label="Password" type="password" value={form.password} onChange={(value) => setForm({ ...form, password: value })} placeholder="10+ characters, mixed case and a symbol" required /><button disabled={busy} className="mt-5 w-full rounded-2xl bg-pine px-5 py-3.5 text-sm font-bold text-white transition hover:bg-ink disabled:cursor-wait disabled:opacity-60">{busy ? "Working…" : mode === "login" ? "Log in" : mode === "register" ? "Create secure workspace" : "Accept secure invitation"}</button>{mode === "register" && <p className="mt-4 text-xs leading-5 text-ink/45">Invited Managers and Building Staff join through an Admin invitation. Public setup never selects an existing organization or privileged role.</p>}</form></div></main>;
}

function Workspace({ session, message, error, onMessage, onError, onLogout }: { session: Session; message: string; error: string; onMessage: (message: string) => void; onError: (message: string) => void; onLogout: () => Promise<void> }) {
  const [properties, setProperties] = useState<Property[]>([]);
  const [tenants, setTenants] = useState<Tenant[]>([]);
  const [staff, setStaff] = useState<StaffMember[]>([]);
  const [busy, setBusy] = useState(false);
  const [selectedPropertyId, setSelectedPropertyId] = useState("all");
  async function refresh() {
    setBusy(true);
    try { const nextProperties = await apiFetch<Property[]>(session.user.role === "BuildingStaff" ? "/api/properties" : "/api/properties?includeArchived=true"); const nextTenants = await apiFetch<Tenant[]>("/api/tenants"); setProperties(nextProperties); setTenants(nextTenants); if (session.user.role !== "BuildingStaff") setStaff(await apiFetch<StaffMember[]>("/api/staff")); }
    catch (caught) { onError(getErrorMessage(caught, "We could not refresh your workspace.")); } finally { setBusy(false); }
  }
  useEffect(() => { void refresh(); }, [session.user.id]);
  async function updateOccupancyStatus(propertyId: string, unitId: string, status: OccupancyStatus) { try { await apiFetch(`/api/properties/${propertyId}/units/${unitId}/occupancy-status`, { method: "PUT", body: JSON.stringify({ status }) }); onMessage("Occupancy status saved separately from tenant details."); await refresh(); return true; } catch (caught) { onError(getErrorMessage(caught, "Could not save occupancy status.")); return false; } }
  async function updateUnit(propertyId: string, unit: Unit, changes: { name?: string; isEnabled?: boolean; isArchived?: boolean }) { try { await apiFetch(`/api/properties/${propertyId}/units/${unit.id}`, { method: "PUT", body: JSON.stringify({ name: changes.name ?? unit.name, isEnabled: changes.isEnabled ?? unit.isEnabled, isArchived: changes.isArchived ?? unit.isArchived }) }); onMessage("Unit settings saved."); await refresh(); } catch (caught) { onError(getErrorMessage(caught, "Could not save unit settings.")); } }
  const visibleProperties = selectedPropertyId === "all" ? properties : properties.filter((property) => property.id === selectedPropertyId);
  return <main className="min-h-screen bg-sand"><header className="border-b border-ink/10 bg-white/70 px-6 py-5 sm:px-10 lg:px-14"><div className="mx-auto flex max-w-7xl items-center justify-between gap-6"><BrandMark /><div className="flex items-center gap-3"><ApiHealth /><div className="hidden text-right sm:block"><p className="text-sm font-bold text-ink">{session.user.fullName}</p><p className="text-xs text-ink/50">{roleLabels[session.user.role]} · {session.organization.name}</p></div><button onClick={onLogout} className="rounded-full border border-ink/15 px-4 py-2 text-xs font-bold text-ink transition hover:bg-white">Log out</button></div></div></header><section className="mx-auto max-w-7xl px-6 py-10 sm:px-10 lg:px-14"><div className="flex flex-wrap items-end justify-between gap-6"><div><p className="text-xs font-bold uppercase tracking-[0.25em] text-pine">Live workspace</p><h1 className="mt-3 text-4xl font-black tracking-[-0.07em] text-ink sm:text-5xl">{session.user.role === "BuildingStaff" ? "Your assigned properties" : "Property operations"}</h1><p className="mt-3 max-w-2xl text-base leading-7 text-ink/55">Real records only. PrimeTect does not infer vacancy from missing tenant information.</p></div><div className="flex flex-wrap items-end gap-3"><label className="text-xs font-bold text-ink">Property<select value={selectedPropertyId} onChange={(event) => setSelectedPropertyId(event.target.value)} className="mt-1 block min-w-48 rounded-xl border border-ink/10 bg-white px-3 py-2.5 text-xs font-normal"><option value="all">All assigned properties</option>{properties.map((property) => <option key={property.id} value={property.id}>{property.name}</option>)}</select></label><span className="rounded-full bg-mint px-3 py-1.5 text-xs font-bold uppercase tracking-[0.16em] text-pine">{busy ? "Refreshing" : "No demo data"}</span></div></div>{message && <Notice tone="success" message={message} onClose={() => onMessage("")} />}{error && <Notice tone="error" message={error} onClose={() => onError("")} />}<div className="mt-10 grid min-w-0 gap-6 xl:grid-cols-[minmax(0,1fr)_minmax(18rem,0.42fr)]"><div className="min-w-0 space-y-5">{visibleProperties.length === 0 ? <EmptyState role={session.user.role} /> : visibleProperties.map((property) => <PropertyCard key={property.id} property={property} tenants={tenants} role={session.user.role} canEdit={session.user.role !== "BuildingStaff"} onRefresh={refresh} onError={onError} onMessage={onMessage} onOccupancyStatus={updateOccupancyStatus} onUnitUpdate={updateUnit} />)}{session.user.role !== "BuildingStaff" && selectedPropertyId === "all" && <PropertySetup onSaved={refresh} onError={onError} onMessage={onMessage} />}</div><aside className="min-w-0 space-y-5"><TenantPanel tenants={tenants} onSaved={refresh} onError={onError} />{session.user.role === "Admin" && <StaffPanel staff={staff} properties={properties} onSaved={refresh} onError={onError} onMessage={onMessage} />}{session.user.role === "Manager" && <InfoCard title="Your access"><p>Managers can work across every active property in {session.organization.name}. Staff assignments do not narrow Manager access.</p></InfoCard>}{session.user.role === "BuildingStaff" && <InfoCard title="Assignment boundary"><p>This view is filtered to properties assigned to your account. Unassigned properties remain unavailable.</p></InfoCard>}</aside></div></section></main>;
}

function PropertyCard({ property, tenants, role, canEdit, onRefresh, onError, onMessage, onOccupancyStatus, onUnitUpdate }: { property: Property; tenants: Tenant[]; role: UserRole; canEdit: boolean; onRefresh: () => Promise<void>; onError: (message: string) => void; onMessage: (message: string) => void; onOccupancyStatus: (propertyId: string, unitId: string, status: OccupancyStatus) => Promise<boolean>; onUnitUpdate: (propertyId: string, unit: Unit, changes: { name?: string; isEnabled?: boolean; isArchived?: boolean }) => Promise<void> }) {
  const [editingProperty, setEditingProperty] = useState(false); const [addingFloor, setAddingFloor] = useState(false); const [showCharges, setShowCharges] = useState(false); const [showBilling, setShowBilling] = useState(false);
  const units = property.floors.flatMap((floor) => floor.units);
  const counts = useMemo(() => units.reduce((summary, unit) => ({ ...summary, [unit.occupancyStatus]: summary[unit.occupancyStatus] + 1 }), { Occupied: 0, Vacant: 0, Unknown: 0 } as Record<OccupancyStatus, number>), [units]);
  return <article className="rounded-[2rem] border border-ink/10 bg-white/75 p-5 shadow-soft sm:p-8"><div className="flex flex-wrap items-start justify-between gap-4"><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><h2 className="break-words text-2xl font-black tracking-[-0.05em] text-ink">{property.name}</h2>{property.isArchived && <span className="rounded-full bg-ink/10 px-2.5 py-1 text-[10px] font-bold uppercase tracking-[0.14em] text-ink/50">Archived</span>}</div><p className="mt-1 break-words text-sm text-ink/50">{propertyTypeLabels[property.propertyType]} · {property.address}</p></div><div className="text-right"><p className="text-3xl font-black tracking-[-0.07em] text-pine">{units.length}</p><p className="text-xs font-bold uppercase tracking-[0.15em] text-ink/40">units</p></div></div><div className="mt-5 flex flex-wrap gap-2 text-xs font-bold"><span className="rounded-full bg-mint px-3 py-1.5 text-pine">{counts.Occupied} occupied</span><span className="rounded-full bg-sand px-3 py-1.5 text-ink/55">{counts.Vacant} vacant</span><span className="rounded-full bg-ink/5 px-3 py-1.5 text-ink/55">{counts.Unknown} unknown</span></div><div className="mt-5 flex flex-wrap gap-2">{canEdit && <><button type="button" onClick={() => setEditingProperty((value) => !value)} className="rounded-xl border border-pine/20 px-3 py-2 text-xs font-bold text-pine">{editingProperty ? "Close property editor" : "Edit property"}</button><button type="button" onClick={() => setShowCharges((value) => !value)} className="rounded-xl border border-pine/20 px-3 py-2 text-xs font-bold text-pine">{showCharges ? "Hide charge defaults" : "Charge defaults"}</button></>}<button type="button" onClick={() => setShowBilling((value) => !value)} className="rounded-xl bg-pine px-3 py-2 text-xs font-bold text-white">{showBilling ? "Hide monthly billing" : "Monthly billing"}</button></div>{editingProperty && <PropertyEditor property={property} onSaved={async () => { setEditingProperty(false); await onRefresh(); }} onError={onError} />}{showCharges && <ChargeEditor propertyId={property.id} scope="property" onError={onError} onMessage={onMessage} />} {showBilling && <BillingPanel property={property} role={role} onError={onError} onMessage={onMessage} /> }<div className="mt-7 space-y-3">{property.floors.map((floor) => <FloorBlock key={floor.id} property={property} floor={floor} tenants={tenants} canEdit={canEdit} onRefresh={onRefresh} onError={onError} onMessage={onMessage} onOccupancyStatus={onOccupancyStatus} onUnitUpdate={onUnitUpdate} />)}</div>{canEdit && !property.isArchived && <div className="mt-5">{addingFloor ? <AddFloorEditor propertyId={property.id} onSaved={async () => { setAddingFloor(false); await onRefresh(); }} onCancel={() => setAddingFloor(false)} onError={onError} /> : <button type="button" onClick={() => setAddingFloor(true)} className="rounded-xl border border-dashed border-pine/30 px-4 py-2.5 text-sm font-bold text-pine">+ Add floor</button>}</div>}</article>;
}

function PropertyEditor({ property, onSaved, onError }: { property: Property; onSaved: () => Promise<void>; onError: (message: string) => void }) {
  const [form, setForm] = useState({ name: property.name, address: property.address, propertyType: property.propertyType, isArchived: property.isArchived }); const [busy, setBusy] = useState(false);
  async function save(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setBusy(true); try { await apiFetch(`/api/properties/${property.id}`, { method: "PUT", body: JSON.stringify(form) }); await onSaved(); } catch (caught) { onError(getErrorMessage(caught, "Could not save property details.")); } finally { setBusy(false); } }
  return <form onSubmit={save} className="mt-5 grid gap-3 rounded-2xl border border-pine/15 bg-mint/50 p-4 sm:grid-cols-2"><Field label="Property name" value={form.name} onChange={(value) => setForm({ ...form, name: value })} required /><Field label="Address" value={form.address} onChange={(value) => setForm({ ...form, address: value })} required /><label className="block text-sm font-bold text-ink sm:col-span-2">Property type<select value={form.propertyType} onChange={(event) => setForm({ ...form, propertyType: event.target.value as PropertyType })} className="mt-2 w-full rounded-xl border border-ink/10 bg-white px-3 py-3 font-normal outline-none focus:border-pine"><option value="ApartmentBuilding">Apartment building</option><option value="IndividualRoomBuilding">Individual-room building</option><option value="Shop">Shops</option></select></label><label className="flex items-center gap-2 text-sm font-bold text-ink sm:col-span-2"><input type="checkbox" checked={form.isArchived} onChange={(event) => setForm({ ...form, isArchived: event.target.checked })} />Archive property</label><div className="sm:col-span-2"><button disabled={busy} className="rounded-xl bg-pine px-4 py-2.5 text-sm font-bold text-white disabled:opacity-50">{busy ? "Saving…" : "Save property"}</button></div></form>;
}

function AddFloorEditor({ propertyId, onSaved, onCancel, onError }: { propertyId: string; onSaved: () => Promise<void>; onCancel: () => void; onError: (message: string) => void }) {
  const [form, setForm] = useState({ name: "", unitCount: "1", unitNames: "" }); const [busy, setBusy] = useState(false);
  async function save(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setBusy(true); const names = splitNames(form.unitNames); try { await apiFetch(`/api/properties/${propertyId}/floors`, { method: "POST", body: JSON.stringify({ name: form.name, unitCount: names.length > 0 ? names.length : Math.max(0, Number(form.unitCount)), unitNames: names.length > 0 ? names : null }) }); await onSaved(); } catch (caught) { onError(getErrorMessage(caught, "Could not add the floor.")); } finally { setBusy(false); } }
  return <form onSubmit={save} className="grid gap-3 rounded-2xl border border-pine/15 bg-mint/50 p-4 sm:grid-cols-[1fr_0.35fr_1.2fr_auto] sm:items-end"><Field label="Floor name" value={form.name} onChange={(value) => setForm({ ...form, name: value })} placeholder="Roof level" required /><Field label="Unit count" type="number" value={form.unitCount} onChange={(value) => setForm({ ...form, unitCount: value })} min="0" required /><Field label="Unit names (optional)" value={form.unitNames} onChange={(value) => setForm({ ...form, unitNames: value })} placeholder="R1, R2" /><div className="flex gap-2"><button disabled={busy} className="rounded-xl bg-pine px-3 py-2.5 text-xs font-bold text-white disabled:opacity-50">{busy ? "Saving…" : "Add"}</button><button type="button" onClick={onCancel} className="rounded-xl border border-ink/15 px-3 py-2.5 text-xs font-bold text-ink/60">Cancel</button></div></form>;
}

function FloorBlock({ property, floor, tenants, canEdit, onRefresh, onError, onMessage, onOccupancyStatus, onUnitUpdate }: { property: Property; floor: Floor; tenants: Tenant[]; canEdit: boolean; onRefresh: () => Promise<void>; onError: (message: string) => void; onMessage: (message: string) => void; onOccupancyStatus: (propertyId: string, unitId: string, status: OccupancyStatus) => Promise<boolean>; onUnitUpdate: (propertyId: string, unit: Unit, changes: { name?: string; isEnabled?: boolean; isArchived?: boolean }) => Promise<void> }) {
  const [editing, setEditing] = useState(false);
  return <div className="rounded-2xl border border-ink/10 p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="font-bold text-ink">{floor.name}</p><p className="text-xs text-ink/40">Sort order {floor.sortOrder} · {floor.units.length} units{floor.isArchived ? " · archived" : ""}</p></div>{canEdit && <button type="button" onClick={() => setEditing((value) => !value)} className="rounded-lg border border-ink/10 px-2.5 py-1.5 text-xs font-bold text-pine">{editing ? "Close floor editor" : "Edit floor"}</button>}</div>{editing && <FloorEditor propertyId={property.id} floor={floor} onSaved={async () => { setEditing(false); await onRefresh(); }} onError={onError} /> }<div className="mt-3 grid min-w-0 gap-2 sm:grid-cols-2">{floor.units.map((unit) => <UnitCard key={unit.id} propertyId={property.id} unit={unit} tenants={tenants} canEdit={canEdit} onError={onError} onMessage={onMessage} onOccupancyStatus={onOccupancyStatus} onUnitUpdate={onUnitUpdate} />)}</div></div>;
}

function FloorEditor({ propertyId, floor, onSaved, onError }: { propertyId: string; floor: Floor; onSaved: () => Promise<void>; onError: (message: string) => void }) {
  const [form, setForm] = useState({ name: floor.name, sortOrder: String(floor.sortOrder), unitNames: floor.units.map((unit) => unit.name).join(", "), isArchived: floor.isArchived }); const [busy, setBusy] = useState(false);
  async function save(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setBusy(true); try { await apiFetch(`/api/properties/${propertyId}/floors/${floor.id}`, { method: "PUT", body: JSON.stringify({ name: form.name, sortOrder: Number(form.sortOrder), unitNames: splitNames(form.unitNames), isArchived: form.isArchived }) }); await onSaved(); } catch (caught) { onError(getErrorMessage(caught, "Could not save floor settings.")); } finally { setBusy(false); } }
  return <form onSubmit={save} className="mt-4 grid gap-3 rounded-xl border border-pine/15 bg-mint/40 p-3 sm:grid-cols-[1fr_0.35fr_1.2fr_auto] sm:items-end"><Field label="Floor name" value={form.name} onChange={(value) => setForm({ ...form, name: value })} required /><Field label="Sort order" type="number" value={form.sortOrder} onChange={(value) => setForm({ ...form, sortOrder: value })} required /><Field label="Unit names" value={form.unitNames} onChange={(value) => setForm({ ...form, unitNames: value })} placeholder="1A, 1B" /><div className="flex flex-wrap items-center gap-2"><label className="flex items-center gap-2 text-xs font-bold text-ink"><input type="checkbox" checked={form.isArchived} onChange={(event) => setForm({ ...form, isArchived: event.target.checked })} />Archive</label><button disabled={busy} className="rounded-xl bg-pine px-3 py-2.5 text-xs font-bold text-white disabled:opacity-50">{busy ? "Saving…" : "Save floor"}</button></div></form>;
}

function UnitCard({ propertyId, unit, tenants, canEdit, onError, onMessage, onOccupancyStatus, onUnitUpdate }: { propertyId: string; unit: Unit; tenants: Tenant[]; canEdit: boolean; onError: (message: string) => void; onMessage: (message: string) => void; onOccupancyStatus: (propertyId: string, unitId: string, status: OccupancyStatus) => Promise<boolean>; onUnitUpdate: (propertyId: string, unit: Unit, changes: { name?: string; isEnabled?: boolean; isArchived?: boolean }) => Promise<void> }) {
  const [showOccupancy, setShowOccupancy] = useState(false); const [showCharges, setShowCharges] = useState(false); const [editing, setEditing] = useState(false);
  return <div className={`min-w-0 rounded-xl px-3 py-3 ${unit.isEnabled && !unit.isArchived ? "bg-sand/80" : "bg-ink/5"}`}><div className="flex flex-wrap items-start justify-between gap-2"><div className="min-w-0"><span className={`break-words text-sm ${unit.isArchived ? "text-ink/35 line-through" : unit.isEnabled ? "font-semibold text-ink" : "font-semibold text-ink/45"}`}>{unit.name}</span><p className="mt-1 text-[10px] font-bold uppercase tracking-[0.12em] text-ink/40">{unit.isEnabled ? "Enabled" : "Disabled"}{unit.isArchived ? " · Archived" : ""}</p></div><select aria-label={`Occupancy for ${unit.name}`} value={unit.occupancyStatus} onChange={(event) => void onOccupancyStatus(propertyId, unit.id, event.target.value as OccupancyStatus)} className="rounded-lg border-0 bg-white px-2 py-1 text-xs font-bold text-pine outline-none ring-1 ring-ink/10"><option value="Unknown">Unknown</option><option value="Occupied">Occupied</option><option value="Vacant">Vacant</option></select></div><div className="mt-3 flex flex-wrap gap-2 text-[10px] font-bold uppercase tracking-[0.1em] text-pine"><button type="button" onClick={() => setShowOccupancy((value) => !value)}>{showOccupancy ? "Hide occupancy" : "Occupancy history"}</button>{canEdit && <><button type="button" onClick={() => setEditing((value) => !value)}>{editing ? "Close unit editor" : "Unit settings"}</button><button type="button" onClick={() => setShowCharges((value) => !value)}>{showCharges ? "Hide charges" : "Unit charges"}</button></>}</div>{editing && canEdit && <UnitEditor propertyId={propertyId} unit={unit} onSaved={() => setEditing(false)} onError={onError} onUnitUpdate={onUnitUpdate} />}{showOccupancy && <OccupancyPanel propertyId={propertyId} unit={unit} tenants={tenants} onStatusChange={onOccupancyStatus} onError={onError} onMessage={onMessage} />}{showCharges && canEdit && <ChargeEditor propertyId={propertyId} unitId={unit.id} scope="unit" onError={onError} onMessage={onMessage} />}</div>;
}

function UnitEditor({ propertyId, unit, onSaved, onError, onUnitUpdate }: { propertyId: string; unit: Unit; onSaved: () => void; onError: (message: string) => void; onUnitUpdate: (propertyId: string, unit: Unit, changes: { name?: string; isEnabled?: boolean; isArchived?: boolean }) => Promise<void> }) {
  const [form, setForm] = useState({ name: unit.name, isEnabled: unit.isEnabled, isArchived: unit.isArchived }); const [busy, setBusy] = useState(false);
  async function save(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setBusy(true); try { await onUnitUpdate(propertyId, unit, form); onSaved(); } catch (caught) { onError(getErrorMessage(caught, "Could not save unit settings.")); } finally { setBusy(false); } }
  return <form onSubmit={save} className="mt-3 grid gap-2 rounded-xl border border-pine/15 bg-white/70 p-3 sm:grid-cols-[1fr_auto_auto_auto] sm:items-end"><Field label="Unit name" value={form.name} onChange={(value) => setForm({ ...form, name: value })} required /><label className="flex items-center gap-2 pb-3 text-xs font-bold text-ink"><input type="checkbox" checked={form.isEnabled} onChange={(event) => setForm({ ...form, isEnabled: event.target.checked })} />Enabled</label><label className="flex items-center gap-2 pb-3 text-xs font-bold text-ink"><input type="checkbox" checked={form.isArchived} onChange={(event) => setForm({ ...form, isArchived: event.target.checked })} />Archived</label><button disabled={busy} className="rounded-xl bg-pine px-3 py-2.5 text-xs font-bold text-white disabled:opacity-50">{busy ? "Saving…" : "Save"}</button></form>;
}

function OccupancyPanel({ propertyId, unit, tenants, onStatusChange, onError, onMessage }: { propertyId: string; unit: Unit; tenants: Tenant[]; onStatusChange: (propertyId: string, unitId: string, status: OccupancyStatus) => Promise<boolean>; onError: (message: string) => void; onMessage: (message: string) => void }) {
  const [history, setHistory] = useState<OccupancyRecord[]>([]); const [tenantId, setTenantId] = useState(""); const [startDate, setStartDate] = useState(todayInput()); const [closeDates, setCloseDates] = useState<Record<string, string>>({}); const [busy, setBusy] = useState(false); const [loading, setLoading] = useState(true); const [localError, setLocalError] = useState("");
  async function loadHistory() { setLoading(true); try { setHistory(await apiFetch<OccupancyRecord[]>(`/api/properties/${propertyId}/units/${unit.id}/occupancy`)); setLocalError(""); } catch (caught) { setLocalError(getErrorMessage(caught, "Could not load occupancy history.")); } finally { setLoading(false); } }
  useEffect(() => { void loadHistory(); }, [propertyId, unit.id]);
  async function moveIn(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setLocalError(""); if (!tenantId) { setLocalError("Choose a tenant record before moving someone in."); return; } setBusy(true); try { await apiFetch(`/api/properties/${propertyId}/units/${unit.id}/occupancy`, { method: "POST", body: JSON.stringify({ tenantId, startDate, endDate: null }) }); const statusSaved = await onStatusChange(propertyId, unit.id, "Occupied"); if (!statusSaved) setLocalError("Move-in was saved, but its separate occupancy status could not be updated."); setTenantId(""); await loadHistory(); onMessage("Move-in saved. Tenant details remain optional and occupancy remains explicitly occupied."); } catch (caught) { const message = getErrorMessage(caught, "Could not save the move-in."); setLocalError(message); onError(message); } finally { setBusy(false); } }
  async function moveOut(record: OccupancyRecord) { const endDate = closeDates[record.id] || todayInput(); setBusy(true); setLocalError(""); try { await apiFetch(`/api/properties/${propertyId}/units/${unit.id}/occupancy/${record.id}/close`, { method: "PUT", body: JSON.stringify({ endDate }) }); const statusSaved = await onStatusChange(propertyId, unit.id, "Vacant"); if (!statusSaved) setLocalError("Move-out history was closed, but its separate occupancy status could not be updated."); await loadHistory(); onMessage("Move-out saved and the occupancy history was preserved."); } catch (caught) { const message = getErrorMessage(caught, "Could not close this occupancy."); setLocalError(message); onError(message); } finally { setBusy(false); } }
  const active = history.find((record) => record.endDate === null);
  return <div className="mt-3 rounded-xl border border-pine/15 bg-white/70 p-3"><div className="flex flex-wrap items-center justify-between gap-2"><p className="text-xs font-bold uppercase tracking-[0.14em] text-pine">Occupancy history</p><span className="text-[10px] font-bold uppercase tracking-[0.12em] text-ink/45">Status is independent</span></div>{localError && <p className="mt-3 rounded-lg bg-rose-100 px-3 py-2 text-xs font-semibold text-rose-800">{localError}</p>}{loading ? <p className="mt-3 text-xs text-ink/50">Loading history…</p> : <><div className="mt-3 space-y-2">{history.length === 0 ? <p className="text-xs text-ink/50">No move-in history yet.</p> : history.map((record) => <div key={record.id} className="rounded-lg bg-sand/70 p-3"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-sm font-bold text-ink">{record.name ?? "Unnamed tenant"}</p><p className="text-xs text-ink/50">{record.phone ?? "No phone"} · {formatDate(record.startDate)} to {record.endDate ? formatDate(record.endDate) : "Current"}</p></div>{record.endDate === null && <span className="rounded-full bg-mint px-2 py-1 text-[10px] font-bold uppercase tracking-[0.1em] text-pine">Current</span>}</div>{record.endDate === null && <div className="mt-3 flex flex-wrap items-end gap-2"><label className="text-xs font-bold text-ink">Move-out date<input type="date" min={record.startDate} value={closeDates[record.id] ?? todayInput()} onChange={(event) => setCloseDates({ ...closeDates, [record.id]: event.target.value })} className="mt-1 block rounded-lg border border-ink/10 bg-white px-2 py-2 text-xs font-normal" /></label><button type="button" disabled={busy} onClick={() => void moveOut(record)} className="rounded-lg bg-pine px-3 py-2 text-xs font-bold text-white disabled:opacity-50">{busy ? "Saving…" : "Close occupancy"}</button></div>}</div>)}</div><form onSubmit={moveIn} className="mt-4 grid gap-2 border-t border-ink/10 pt-4 sm:grid-cols-[1fr_auto_auto] sm:items-end"><label className="block text-xs font-bold text-ink">Tenant record<select required value={tenantId} onChange={(event) => setTenantId(event.target.value)} className="mt-1 w-full rounded-lg border border-ink/10 bg-white px-2 py-2 text-xs font-normal"><option value="">Choose tenant</option>{tenants.map((tenant) => <option key={tenant.id} value={tenant.id}>{tenant.name ?? "Unnamed tenant"}{tenant.phone ? ` · ${tenant.phone}` : ""}</option>)}</select></label><label className="block text-xs font-bold text-ink">Move-in date<input required type="date" value={startDate} onChange={(event) => setStartDate(event.target.value)} className="mt-1 rounded-lg border border-ink/10 bg-white px-2 py-2 text-xs font-normal" /></label><button disabled={busy || Boolean(active)} className="rounded-lg border border-pine/25 px-3 py-2 text-xs font-bold text-pine disabled:cursor-not-allowed disabled:opacity-50">{active ? "Close current occupancy first" : "Save move-in"}</button></form>{tenants.length === 0 && <p className="mt-2 text-[11px] text-ink/45">Create a tenant record first. Name and phone can each remain blank.</p>}</>}</div>;
}

function ChargeEditor({ propertyId, unitId, scope, onError, onMessage }: { propertyId: string; unitId?: string; scope: "property" | "unit"; onError: (message: string) => void; onMessage: (message: string) => void }) {
  const [settings, setSettings] = useState<ChargeDraft[]>([]); const [loading, setLoading] = useState(true); const [busy, setBusy] = useState(false); const [localError, setLocalError] = useState(""); const endpoint = scope === "property" ? `/api/properties/${propertyId}/charges` : `/api/properties/${propertyId}/units/${unitId}/charges`;
  async function load() { setLoading(true); try { const result = await apiFetch<ChargeConfiguration[]>(endpoint); setSettings(result.map(toChargeDraft)); setLocalError(""); } catch (caught) { setLocalError(getErrorMessage(caught, "Could not load charge settings.")); } finally { setLoading(false); } }
  useEffect(() => { void load(); }, [endpoint]);
  function addSetting() { setSettings([...settings, { key: makeKey(), chargeType: "Electricity", mode: scope === "property" ? "Custom" : "Inherited", billingMonth: currentMonthInput(), amount: "", customLabel: "" }]); }
  function updateSetting(key: string, changes: Partial<ChargeDraft>) { setSettings(settings.map((setting) => setting.key === key ? { ...setting, ...changes } : setting)); }
  async function save() {
    setLocalError(""); const seen = new Set<string>();
    for (const setting of settings) { if (!setting.billingMonth) { setLocalError("Every charge needs an effective billing month."); return; } const uniqueKey = `${setting.chargeType}:${setting.billingMonth}`; if (seen.has(uniqueKey)) { setLocalError("Only one setting per charge type and billing month is allowed."); return; } seen.add(uniqueKey); if (setting.mode === "Custom" && (!setting.amount.trim() || Number.isNaN(Number(setting.amount)) || Number(setting.amount) < 0)) { setLocalError("Custom charges require a non-negative decimal amount or rate."); return; } if (setting.chargeType === "Custom" && setting.mode === "Custom" && !setting.customLabel.trim()) { setLocalError("Custom charges require a label."); return; } }
    setBusy(true); try { const items = settings.map((setting) => ({ chargeType: setting.chargeType, mode: setting.mode, billingMonth: `${setting.billingMonth}-01`, amount: setting.mode === "Custom" ? Number(setting.amount) : null, customLabel: setting.customLabel.trim() || null })); const result = await apiFetch<ChargeConfiguration[]>(endpoint, { method: "PUT", body: JSON.stringify({ items }) }); setSettings(result.map(toChargeDraft)); onMessage(scope === "property" ? "Property charge defaults saved." : "Unit charge overrides saved."); } catch (caught) { const message = getErrorMessage(caught, "Could not save charge settings."); setLocalError(message); onError(message); } finally { setBusy(false); }
  }
  return <section className="mt-5 rounded-2xl border border-sun/40 bg-sun/10 p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[0.16em] text-pine">{scope === "property" ? "Property charge defaults" : "Unit charge settings"}</p><p className="mt-1 text-xs leading-5 text-ink/55">{scope === "property" ? "Set custom defaults or explicitly disable a charge." : "Choose inherited defaults, a unit override, or a disabled charge."} Effective month and decimal amounts are saved with each row.</p></div><button type="button" onClick={addSetting} className="rounded-xl border border-pine/20 bg-white/70 px-3 py-2 text-xs font-bold text-pine">+ Add charge</button></div>{localError && <p className="mt-3 rounded-lg bg-rose-100 px-3 py-2 text-xs font-semibold text-rose-800">{localError}</p>}{loading ? <p className="mt-4 text-xs text-ink/50">Loading charges…</p> : settings.length === 0 ? <p className="mt-4 text-xs text-ink/50">No charge settings saved yet.</p> : <div className="mt-4 space-y-3">{settings.map((setting) => <div key={setting.key} className="grid gap-2 rounded-xl border border-ink/10 bg-white/70 p-3 sm:grid-cols-[1fr_0.9fr_0.85fr_0.8fr]"><label className="text-xs font-bold text-ink">Charge type<select value={setting.chargeType} onChange={(event) => updateSetting(setting.key, { chargeType: event.target.value as ChargeType })} className="mt-1 w-full rounded-lg border border-ink/10 bg-white px-2 py-2 text-xs font-normal">{chargeTypes.map((type) => <option key={type} value={type}>{chargeTypeLabels[type]}</option>)}</select></label><label className="text-xs font-bold text-ink">Mode<select value={setting.mode} onChange={(event) => updateSetting(setting.key, { mode: event.target.value as ChargeSettingMode })} className="mt-1 w-full rounded-lg border border-ink/10 bg-white px-2 py-2 text-xs font-normal">{scope === "unit" && <option value="Inherited">Inherited</option>}<option value="Custom">Custom override</option><option value="Disabled">Disabled</option></select></label><label className="text-xs font-bold text-ink">Billing month<input type="month" value={setting.billingMonth} onChange={(event) => updateSetting(setting.key, { billingMonth: event.target.value })} className="mt-1 w-full rounded-lg border border-ink/10 bg-white px-2 py-2 text-xs font-normal" /></label><label className="text-xs font-bold text-ink">Amount / rate<input type="number" min="0" step="0.0001" inputMode="decimal" disabled={setting.mode !== "Custom"} value={setting.amount} onChange={(event) => updateSetting(setting.key, { amount: event.target.value })} placeholder={setting.mode === "Custom" ? "0.0000" : "Not used"} className="mt-1 w-full rounded-lg border border-ink/10 bg-white px-2 py-2 text-xs font-normal disabled:bg-ink/5" /></label>{setting.chargeType === "Custom" && setting.mode === "Custom" && <label className="text-xs font-bold text-ink sm:col-span-2">Custom label<input value={setting.customLabel} onChange={(event) => updateSetting(setting.key, { customLabel: event.target.value })} placeholder="Lift maintenance" className="mt-1 w-full rounded-lg border border-ink/10 bg-white px-2 py-2 text-xs font-normal" /></label>}<p className="self-end text-[11px] leading-5 text-ink/50 sm:col-span-2">{setting.mode === "Inherited" ? "Uses the property default for this month." : setting.mode === "Disabled" ? "This charge is explicitly disabled." : "Uses this decimal override."}</p></div>)}</div>}<div className="mt-4 flex items-center justify-between gap-3"><span className="text-[11px] text-ink/45">Configuration only — billing calculations are not implemented.</span><button type="button" disabled={busy || loading} onClick={() => void save()} className="rounded-xl bg-pine px-4 py-2.5 text-xs font-bold text-white disabled:opacity-50">{busy ? "Saving…" : "Save charges"}</button></div></section>;
}

function BillingPanel({ property, role, onError, onMessage }: { property: Property; role: UserRole; onError: (message: string) => void; onMessage: (message: string) => void }) {
  const [month, setMonth] = useState(currentMonthInput());
  const [floorId, setFloorId] = useState("all");
  const [cycle, setCycle] = useState<BillingCycle | null>(null);
  const [readings, setReadings] = useState<Record<string, { previous: string; current: string }>>({});
  const [returnReason, setReturnReason] = useState("");
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [localError, setLocalError] = useState("");
  const canReview = role === "Admin" || role === "Manager";

  function setCycleState(next: BillingCycle | null) {
    setCycle(next);
    if (!next) {
      setReadings({});
      return;
    }
    setReadings(Object.fromEntries(next.bills.map((bill) => {
      const line = bill.charges.find((charge) => charge.isMetered);
      return [bill.id, { previous: line?.previousReading === null || line?.previousReading === undefined ? "" : String(line.previousReading), current: line?.currentReading === null || line?.currentReading === undefined ? "" : String(line.currentReading) }];
    })));
  }

  async function load() {
    setLoading(true);
    try {
      setCycleState(await apiFetch<BillingCycle>(`/api/properties/${property.id}/billing-cycles/${month}`));
      setLocalError("");
    } catch (caught) {
      if (caught instanceof ApiError && caught.status === 404) {
        setCycleState(null);
        setLocalError("");
      } else {
        setLocalError(getErrorMessage(caught, "Could not load the billing cycle."));
      }
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => { void load(); }, [property.id, month]);

  async function generate() {
    setBusy(true); setLocalError("");
    try { setCycleState(await apiFetch<BillingCycle>(`/api/properties/${property.id}/billing-cycles`, { method: "POST", body: JSON.stringify({ billingMonth: `${month}-01` }) })); onMessage("Monthly billing draft generated from the selected charge and occupancy snapshots."); }
    catch (caught) { setLocalError(getErrorMessage(caught, "Could not generate this billing cycle.")); }
    finally { setBusy(false); }
  }

  function readingValue(value: string) { if (!value.trim()) return null; const parsed = Number(value); return Number.isFinite(parsed) ? parsed : Number.NaN; }

  async function saveReadings() {
    if (!cycle) return;
    const entries = cycle.bills.flatMap((bill) => bill.charges.some((charge) => charge.isMetered) ? [{ unitBillId: bill.id, previousReading: readingValue(readings[bill.id]?.previous ?? ""), currentReading: readingValue(readings[bill.id]?.current ?? "") }] : []);
    if (entries.some((entry) => Number.isNaN(entry.previousReading) || Number.isNaN(entry.currentReading))) { setLocalError("Meter readings must be valid decimal numbers or left blank."); return; }
    setBusy(true); setLocalError("");
    try { setCycleState(await apiFetch<BillingCycle>(`/api/properties/${property.id}/billing-cycles/${cycle.id}/meter-readings`, { method: "PUT", body: JSON.stringify({ expectedVersion: cycle.version, entries, reason: "Meter readings saved from the monthly billing workspace." }) })); onMessage("Meter readings saved as a draft."); }
    catch (caught) { setLocalError(getErrorMessage(caught, "Could not save the meter readings.")); }
    finally { setBusy(false); }
  }

  async function transition(action: "submit" | "return" | "approve") {
    if (!cycle) return;
    if (action === "return" && !returnReason.trim()) { setLocalError("A reason is required when returning a cycle for correction."); return; }
    setBusy(true); setLocalError("");
    try { setCycleState(await apiFetch<BillingCycle>(`/api/properties/${property.id}/billing-cycles/${cycle.id}/${action}`, { method: "POST", body: JSON.stringify({ expectedVersion: cycle.version, reason: action === "return" ? returnReason : undefined }) })); setReturnReason(""); onMessage(action === "approve" ? "Billing cycle approved. This snapshot is now immutable; approved is not collected." : action === "return" ? "Billing cycle returned for correction." : "Billing cycle submitted for review."); }
    catch (caught) { setLocalError(getErrorMessage(caught, `Could not ${action} this billing cycle.`)); }
    finally { setBusy(false); }
  }

  const floorForUnit = new Map(property.floors.flatMap((floor) => floor.units.map((unit) => [unit.id, floor.id] as const)));
  const visibleBills = cycle?.bills.filter((bill) => floorId === "all" || floorForUnit.get(bill.unitId) === floorId) ?? [];
  const editable = cycle?.status === "Draft" || cycle?.status === "Returned";
  return <section className="mt-5 rounded-2xl border border-pine/20 bg-mint/35 p-4 sm:p-5"><div className="flex flex-wrap items-end justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[0.16em] text-pine">Monthly billing</p><p className="mt-1 max-w-2xl text-xs leading-5 text-ink/55">Draft calculation and meter review only. Approved amounts are not collected, and approved snapshots never change when rates change later.</p></div><div className="flex flex-wrap gap-2"><label className="text-xs font-bold text-ink">Month<input type="month" value={month} onChange={(event) => setMonth(event.target.value)} className="mt-1 block rounded-lg border border-ink/10 bg-white px-2 py-2 text-xs font-normal" /></label><label className="text-xs font-bold text-ink">Floor<select value={floorId} onChange={(event) => setFloorId(event.target.value)} className="mt-1 block min-w-28 rounded-lg border border-ink/10 bg-white px-2 py-2 text-xs font-normal"><option value="all">All floors</option>{property.floors.map((floor) => <option key={floor.id} value={floor.id}>{floor.name}</option>)}</select></label></div></div>{localError && <p className="mt-3 rounded-lg bg-rose-100 px-3 py-2 text-xs font-semibold text-rose-800">{localError}</p>}{loading ? <p className="mt-4 text-xs text-ink/50">Loading billing cycle…</p> : !cycle ? <div className="mt-4 flex flex-wrap items-center justify-between gap-3 rounded-xl border border-dashed border-pine/25 bg-white/60 p-4"><p className="text-xs text-ink/55">No billing cycle exists for {month}. Generation is one-time per property and month.</p>{canReview ? <button type="button" disabled={busy} onClick={() => void generate()} className="rounded-xl bg-pine px-3 py-2 text-xs font-bold text-white disabled:opacity-50">{busy ? "Generating…" : "Generate draft"}</button> : <span className="text-xs font-semibold text-ink/50">A Manager or Admin must generate this draft.</span>}</div> : <><div className="mt-4 grid gap-2 sm:grid-cols-4"><Summary label="Status" value={cycle.status} /><Summary label="Draft total" value={`Tk ${money(cycle.draftTotal)}`} /><Summary label="Approved total" value={cycle.approvedTotal === null ? "—" : `Tk ${money(cycle.approvedTotal)}`} note="Not collected" /><Summary label="Needs review" value={String(cycle.blockingBillCount)} /></div>{cycle.returnReason && <p className="mt-3 rounded-lg bg-sun/20 px-3 py-2 text-xs text-ink/70"><strong>Returned reason:</strong> {cycle.returnReason}</p>}<div className="mt-4 hidden overflow-x-auto rounded-xl border border-ink/10 bg-white/70 sm:block"><table className="w-full min-w-[760px] text-left text-xs"><thead className="border-b border-ink/10 text-[10px] uppercase tracking-[0.12em] text-ink/45"><tr><th className="p-3">Unit / occupancy snapshot</th><th className="p-3">Charges</th><th className="p-3">Meter entry</th><th className="p-3 text-right">Draft total</th></tr></thead><tbody>{visibleBills.map((bill) => <BillingTableRow key={bill.id} bill={bill} reading={readings[bill.id]} editable={Boolean(editable)} onReadingChange={(field, value) => setReadings({ ...readings, [bill.id]: { previous: readings[bill.id]?.previous ?? "", current: readings[bill.id]?.current ?? "", [field]: value } })} />)}</tbody></table></div><div className="mt-4 space-y-3 sm:hidden">{visibleBills.map((bill) => <BillingMobileCard key={bill.id} bill={bill} reading={readings[bill.id]} editable={Boolean(editable)} onReadingChange={(field, value) => setReadings({ ...readings, [bill.id]: { previous: readings[bill.id]?.previous ?? "", current: readings[bill.id]?.current ?? "", [field]: value } })} />)}</div><div className="mt-4 flex flex-wrap items-end justify-between gap-3"><div className="flex flex-wrap gap-2">{editable && <button type="button" disabled={busy} onClick={() => void saveReadings()} className="rounded-xl border border-pine/20 bg-white px-3 py-2.5 text-xs font-bold text-pine disabled:opacity-50">{busy ? "Saving…" : "Save draft"}</button>}{editable && <button type="button" disabled={busy || cycle.blockingBillCount > 0} onClick={() => void transition("submit")} className="rounded-xl bg-pine px-3 py-2.5 text-xs font-bold text-white disabled:cursor-not-allowed disabled:opacity-50">Submit for review</button>}{canReview && cycle.status === "Submitted" && <><button type="button" disabled={busy} onClick={() => void transition("approve")} className="rounded-xl bg-pine px-3 py-2.5 text-xs font-bold text-white disabled:opacity-50">Approve</button><button type="button" disabled={busy} onClick={() => void transition("return")} className="rounded-xl border border-sun/60 bg-sun/15 px-3 py-2.5 text-xs font-bold text-ink disabled:opacity-50">Return</button></>}</div>{canReview && cycle.status === "Submitted" && <label className="min-w-56 text-xs font-bold text-ink">Return reason<input value={returnReason} onChange={(event) => setReturnReason(event.target.value)} placeholder="Explain the correction needed" className="mt-1 block w-full rounded-lg border border-ink/10 bg-white px-2 py-2 text-xs font-normal" /></label>}</div><p className="mt-3 text-[11px] leading-5 text-ink/45">Missing readings, negative consumption, vacant units, and partial-month occupancy remain blocked for review. Electricity below Tk200 shows a warning only; no minimum fee is added.</p></>}</section>;
}

function BillingTableRow({ bill, reading, editable, onReadingChange }: { bill: BillingUnitBill; reading?: { previous: string; current: string }; editable: boolean; onReadingChange: (field: "previous" | "current", value: string) => void }) {
  const meter = bill.charges.find((charge) => charge.isMetered);
  return <tr className="border-b border-ink/5 align-top last:border-b-0"><td className="p-3"><p className="font-bold text-ink">{bill.unitName}</p><p className="mt-1 text-[11px] text-ink/50">{bill.tenantName ?? "Unnamed tenant"} · {bill.tenantPhone ?? "No phone"}</p>{bill.blockingReason && <p className="mt-2 max-w-52 rounded-md bg-rose-100 px-2 py-1 text-[10px] font-semibold leading-4 text-rose-800">{bill.blockingReason}</p>}{bill.electricityWarning && <p className="mt-2 rounded-md bg-sun/20 px-2 py-1 text-[10px] font-semibold text-ink">Electricity below Tk200 warning</p>}</td><td className="p-3"><div className="space-y-1.5">{bill.charges.map((charge) => <div key={charge.id} className="flex min-w-44 justify-between gap-3"><span className="text-ink/60">{charge.chargeName}{charge.isMetered && charge.rate !== null ? ` · rate ${charge.rate}` : ""}</span><span className="font-semibold text-ink">Tk {money(charge.amount)}</span></div>)}</div></td><td className="p-3">{meter ? <div className="grid min-w-44 gap-2"><ReadingInput label={meter.previousReadingSource === "ApprovedPeriod" ? "Previous (approved)" : "Opening reading"} value={reading?.previous ?? ""} disabled={!editable || meter.previousReadingSource === "ApprovedPeriod"} onChange={(value) => onReadingChange("previous", value)} /><ReadingInput label="Current reading" value={reading?.current ?? ""} disabled={!editable} onChange={(value) => onReadingChange("current", value)} />{meter.consumptionUnits !== null && <p className="text-[10px] text-ink/45">{meter.consumptionUnits} units × Tk {meter.rate}</p>}</div> : <span className="text-[11px] text-ink/45">No meter input required</span>}</td><td className="p-3 text-right font-black text-pine">Tk {money(bill.total)}</td></tr>;
}

function BillingMobileCard({ bill, reading, editable, onReadingChange }: { bill: BillingUnitBill; reading?: { previous: string; current: string }; editable: boolean; onReadingChange: (field: "previous" | "current", value: string) => void }) {
  const meter = bill.charges.find((charge) => charge.isMetered);
  return <article className="rounded-xl border border-ink/10 bg-white/70 p-3"><div className="flex items-start justify-between gap-3"><div><p className="font-bold text-ink">{bill.unitName}</p><p className="mt-1 text-[11px] text-ink/50">{bill.tenantName ?? "Unnamed tenant"} · {bill.tenantPhone ?? "No phone"}</p></div><p className="font-black text-pine">Tk {money(bill.total)}</p></div>{bill.blockingReason && <p className="mt-3 rounded-md bg-rose-100 px-2 py-1 text-[10px] font-semibold leading-4 text-rose-800">{bill.blockingReason}</p>}{bill.electricityWarning && <p className="mt-2 rounded-md bg-sun/20 px-2 py-1 text-[10px] font-semibold text-ink">Electricity below Tk200 warning</p>}<div className="mt-3 space-y-1.5">{bill.charges.map((charge) => <div key={charge.id} className="flex justify-between gap-3 text-xs"><span className="text-ink/60">{charge.chargeName}{charge.isMetered && charge.rate !== null ? ` · rate ${charge.rate}` : ""}</span><span className="font-semibold text-ink">Tk {money(charge.amount)}</span></div>)}</div>{meter ? <div className="mt-3 grid gap-2 border-t border-ink/10 pt-3"><ReadingInput label={meter.previousReadingSource === "ApprovedPeriod" ? "Previous (approved)" : "Opening reading"} value={reading?.previous ?? ""} disabled={!editable || meter.previousReadingSource === "ApprovedPeriod"} onChange={(value) => onReadingChange("previous", value)} /><ReadingInput label="Current reading" value={reading?.current ?? ""} disabled={!editable} onChange={(value) => onReadingChange("current", value)} />{meter.consumptionUnits !== null && <p className="text-[10px] text-ink/45">{meter.consumptionUnits} units × Tk {meter.rate}</p>}</div> : <p className="mt-3 border-t border-ink/10 pt-3 text-[11px] text-ink/45">Fixed-charge-only unit — no meter input required.</p>}</article>;
}

function ReadingInput({ label, value, disabled, onChange }: { label: string; value: string; disabled: boolean; onChange: (value: string) => void }) { return <label className="text-[10px] font-bold text-ink">{label}<input type="number" step="0.0001" min="0" inputMode="decimal" value={value} disabled={disabled} onChange={(event) => onChange(event.target.value)} className="mt-1 w-full rounded-lg border border-ink/10 bg-white px-2 py-2 text-xs font-normal disabled:bg-ink/5" /></label>; }
function Summary({ label, value, note }: { label: string; value: string; note?: string }) { return <div className="rounded-xl border border-ink/10 bg-white/70 px-3 py-2.5"><p className="text-[10px] font-bold uppercase tracking-[0.12em] text-ink/45">{label}</p><p className="mt-1 text-sm font-black text-pine">{value}</p>{note && <p className="text-[10px] text-ink/45">{note}</p>}</div>; }

function PropertySetup({ onSaved, onError, onMessage }: { onSaved: () => Promise<void>; onError: (message: string) => void; onMessage: (message: string) => void }) {
  const [form, setForm] = useState({ name: "", address: "", propertyType: "ApartmentBuilding" as PropertyType, floors: initialFloors }); const [preview, setPreview] = useState<PropertyPreview | null>(null); const [busy, setBusy] = useState(false);
  function updateFloor(index: number, field: keyof FloorDraft, value: string) { setForm((current) => ({ ...current, floors: current.floors.map((floor, floorIndex) => floorIndex === index ? { ...floor, [field]: field === "unitCount" ? Math.max(0, Number(value)) : value } : floor) })); }
  function payload() { return { ...form, floors: form.floors.map((floor) => { const unitNames = splitNames(floor.unitNames); return { name: floor.name, unitCount: unitNames.length > 0 ? unitNames.length : floor.unitCount, unitNames }; }) }; }
  async function showPreview() { setBusy(true); try { setPreview(await apiFetch<PropertyPreview>("/api/properties/preview", { method: "POST", body: JSON.stringify(payload()) })); onError(""); } catch (caught) { onError(getErrorMessage(caught, "Could not generate the unit preview.")); } finally { setBusy(false); } }
  async function saveProperty() { setBusy(true); try { await apiFetch("/api/properties", { method: "POST", body: JSON.stringify(payload()) }); setForm({ name: "", address: "", propertyType: "ApartmentBuilding", floors: initialFloors }); setPreview(null); onMessage("Property saved as a real record."); await onSaved(); } catch (caught) { onError(getErrorMessage(caught, "Could not save the property.")); } finally { setBusy(false); } }
  return <section className="rounded-[2rem] border border-pine/20 bg-mint/60 p-5 sm:p-8"><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[0.2em] text-pine">Dynamic setup</p><h2 className="mt-2 text-2xl font-black tracking-[-0.05em] text-ink">Shape a property floor by floor</h2><p className="mt-2 max-w-xl text-sm leading-6 text-ink/55">Use named units when you have them, or leave names blank to preview generated units. Each floor can have a different count.</p></div><span className="rounded-full bg-white/70 px-3 py-1.5 text-xs font-bold text-pine">Admin + Manager</span></div><div className="mt-6 grid gap-4 sm:grid-cols-2"><Field label="Property name" value={form.name} onChange={(value) => setForm({ ...form, name: value })} placeholder="Riverside House" required /><Field label="Address" value={form.address} onChange={(value) => setForm({ ...form, address: value })} placeholder="12 River Road" required /><label className="block text-sm font-bold text-ink sm:col-span-2">Property type<select value={form.propertyType} onChange={(event) => setForm({ ...form, propertyType: event.target.value as PropertyType })} className="mt-2 w-full rounded-xl border border-ink/10 bg-white px-3 py-3 font-normal outline-none focus:border-pine"><option value="ApartmentBuilding">Apartment building</option><option value="IndividualRoomBuilding">Individual-room building</option><option value="Shop">Shops</option></select></label></div><div className="mt-6 space-y-3">{form.floors.map((floor, index) => <div key={`${index}-${floor.name}`} className="grid gap-3 rounded-2xl border border-pine/10 bg-white/60 p-4 sm:grid-cols-[1fr_0.35fr_1.2fr_auto] sm:items-end"><Field label={`Floor ${index + 1} name`} value={floor.name} onChange={(value) => updateFloor(index, "name", value)} placeholder="Floor 1" required /><Field label="Unit count" type="number" value={String(floor.unitCount)} onChange={(value) => updateFloor(index, "unitCount", value)} placeholder="2" min="0" required /><Field label="Unit names (optional)" value={floor.unitNames} onChange={(value) => updateFloor(index, "unitNames", value)} placeholder="1A, 1B" /><button type="button" onClick={() => setForm({ ...form, floors: form.floors.filter((_, floorIndex) => floorIndex !== index) })} className="rounded-xl px-3 py-3 text-xs font-bold text-ink/45 hover:bg-white hover:text-rose-500">Remove</button></div>)}</div><div className="mt-4 flex flex-wrap gap-3"><button type="button" onClick={() => setForm({ ...form, floors: [...form.floors, { name: `Floor ${form.floors.length + 1}`, unitCount: 1, unitNames: "" }] })} className="rounded-xl border border-pine/20 bg-white/60 px-4 py-2.5 text-sm font-bold text-pine">+ Add floor</button><button type="button" disabled={busy} onClick={() => void showPreview()} className="rounded-xl bg-pine px-4 py-2.5 text-sm font-bold text-white disabled:opacity-50">{busy ? "Working…" : "Preview generated units"}</button><button type="button" disabled={busy} onClick={() => void saveProperty()} className="rounded-xl border border-pine/25 px-4 py-2.5 text-sm font-bold text-pine disabled:opacity-50">Save property</button></div>{preview && <div className="mt-6 rounded-2xl border border-pine/15 bg-white/70 p-5"><p className="text-xs font-bold uppercase tracking-[0.18em] text-pine">Generated-unit preview</p><div className="mt-4 grid gap-3 sm:grid-cols-2">{preview.floors.map((floor) => <div key={floor.sortOrder} className="rounded-xl bg-sand/70 p-3"><p className="font-bold text-ink">{floor.name}</p><p className="mt-1 text-sm text-ink/55">{floor.units.map((unit) => unit.name).join(" · ") || "No units"}</p></div>)}</div></div>}</section>;
}

function TenantPanel({ tenants, onSaved, onError }: { tenants: Tenant[]; onSaved: () => Promise<void>; onError: (message: string) => void }) {
  const [name, setName] = useState(""); const [phone, setPhone] = useState(""); const [busy, setBusy] = useState(false);
  async function addTenant(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setBusy(true); try { await apiFetch("/api/tenants", { method: "POST", body: JSON.stringify({ name: name || null, phone: phone || null }) }); setName(""); setPhone(""); await onSaved(); } catch (caught) { onError(getErrorMessage(caught, "Could not save the tenant record.")); } finally { setBusy(false); } }
  return <InfoCard title="Tenant foundation"><form onSubmit={addTenant} className="space-y-3"><p className="text-xs leading-5 text-ink/50">Name and phone are independent. Either can be added later; onboarding is currently <strong>Not connected</strong>.</p><Field label="Name (optional)" value={name} onChange={setName} placeholder="Tenant name" /><Field label="Phone (optional)" value={phone} onChange={setPhone} placeholder="Phone number" /><button disabled={busy} className="w-full rounded-xl bg-pine px-4 py-2.5 text-sm font-bold text-white disabled:opacity-50">{busy ? "Saving…" : "Add tenant record"}</button></form><div className="mt-5 space-y-2">{tenants.length === 0 ? <p className="text-sm text-ink/45">No real tenant records yet.</p> : tenants.slice(0, 8).map((tenant) => <div key={tenant.id} className="flex items-center justify-between gap-3 rounded-xl bg-sand/70 px-3 py-2.5"><div className="min-w-0"><p className="break-words text-sm font-bold text-ink">{tenant.name ?? "Unnamed tenant"}</p><p className="text-xs text-ink/45">{tenant.phone ?? "No phone"}</p></div><span className="shrink-0 text-[10px] font-bold uppercase tracking-[0.12em] text-pine">Not connected</span></div>)}</div></InfoCard>;
}

function StaffPanel({ staff, properties, onSaved, onError, onMessage }: { staff: StaffMember[]; properties: Property[]; onSaved: () => Promise<void>; onError: (message: string) => void; onMessage: (message: string) => void }) {
  const [email, setEmail] = useState(""); const [role, setRole] = useState<"Manager" | "BuildingStaff">("BuildingStaff"); const [inviteToken, setInviteToken] = useState(""); const [busy, setBusy] = useState(false);
  async function invite(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setBusy(true); try { const response = await apiFetch<{ invitationToken: string }>("/api/staff/invitations", { method: "POST", body: JSON.stringify({ email, role }) }); setInviteToken(response.invitationToken); setEmail(""); onMessage("Invitation created for manual sharing. No email was sent because delivery is not connected."); } catch (caught) { onError(getErrorMessage(caught, "Could not create the invitation.")); } finally { setBusy(false); } }
  async function toggleAssignment(member: StaffMember, propertyId: string) { const assigned = member.propertyIds.includes(propertyId); setBusy(true); try { await apiFetch(`/api/properties/${propertyId}/staff/${member.user.id}`, { method: assigned ? "DELETE" : "POST" }); await onSaved(); } catch (caught) { onError(getErrorMessage(caught, "Could not update the staff assignment.")); } finally { setBusy(false); } }
  return <InfoCard title="Staff access"><form onSubmit={invite} className="space-y-3"><p className="text-xs leading-5 text-ink/50">Only Admins can invite Managers and Building Staff. Share the one-time token manually and securely.</p><Field label="Invite email" type="email" value={email} onChange={setEmail} placeholder="staff@example.com" required /><label className="block text-sm font-bold text-ink">Role<select value={role} onChange={(event) => setRole(event.target.value as "Manager" | "BuildingStaff")} className="mt-2 w-full rounded-xl border border-ink/10 bg-white px-3 py-3 font-normal outline-none focus:border-pine"><option value="BuildingStaff">Building staff</option><option value="Manager">Manager</option></select></label><button disabled={busy} className="w-full rounded-xl bg-pine px-4 py-2.5 text-sm font-bold text-white disabled:opacity-50">{busy ? "Working…" : "Create invitation"}</button></form>{inviteToken && <div className="mt-4 rounded-xl border border-sun/50 bg-sun/15 p-3"><p className="text-[10px] font-bold uppercase tracking-[0.12em] text-ink/55">Manual invitation token</p><code className="mt-2 block break-all text-xs text-ink">{inviteToken}</code><p className="mt-2 text-[11px] leading-4 text-ink/55">The recipient should choose “Accept invitation” and paste this one-time token. No email was sent.</p></div>}<div className="mt-6 space-y-4">{staff.length === 0 ? <p className="text-sm text-ink/45">No invited accounts yet.</p> : staff.map((member) => <div key={member.user.id} className="rounded-xl border border-ink/10 p-3"><div><p className="text-sm font-bold text-ink">{member.user.fullName}</p><p className="text-xs text-ink/45">{member.user.email} · {roleLabels[member.user.role]}</p></div>{member.user.role === "BuildingStaff" && <div className="mt-3 grid gap-2">{properties.filter((property) => !property.isArchived).map((property) => <label key={property.id} className="flex items-center gap-2 text-xs text-ink/65"><input type="checkbox" checked={member.propertyIds.includes(property.id)} onChange={() => void toggleAssignment(member, property.id)} />{property.name}</label>)}</div>}</div>)}</div></InfoCard>;
}

function Field({ label, value, onChange, placeholder, type = "text", required = false, min }: { label: string; value: string; onChange: (value: string) => void; placeholder?: string; type?: string; required?: boolean; min?: string }) { return <label className="block min-w-0 text-sm font-bold text-ink">{label}<input required={required} min={min} type={type} value={value} onChange={(event) => onChange(event.target.value)} placeholder={placeholder} className="mt-2 w-full min-w-0 rounded-xl border border-ink/10 bg-white px-3 py-3 font-normal outline-none transition placeholder:text-ink/30 focus:border-pine focus:ring-2 focus:ring-pine/10" /></label>; }
function AuthTab({ active, onClick, children }: { active: boolean; onClick: () => void; children: ReactNode }) { return <button type="button" className={`pb-4 ${active ? "border-b-2 border-pine text-pine" : "text-ink/40"}`} onClick={onClick}>{children}</button>; }
function BrandMark() { return <div className="flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-2xl bg-pine text-lg font-black text-white shadow-soft">P</div><span className="text-lg font-black tracking-[-0.04em] text-ink">PrimeTect</span></div>; }
function InfoCard({ title, children }: { title: string; children: ReactNode }) { return <section className="rounded-[2rem] border border-ink/10 bg-white/75 p-6 shadow-soft"><h2 className="text-lg font-black tracking-[-0.04em] text-ink">{title}</h2><div className="mt-4 text-sm leading-6 text-ink/60">{children}</div></section>; }
function Notice({ tone, message, onClose }: { tone: "success" | "error"; message: string; onClose: () => void }) { return <div className={`mt-6 flex items-center justify-between gap-4 rounded-2xl px-4 py-3 text-sm ${tone === "success" ? "bg-mint text-pine" : "bg-rose-100 text-rose-800"}`}><span>{message}</span><button onClick={onClose} className="font-bold">×</button></div>; }
function EmptyState({ role }: { role: UserRole }) { return <div className="rounded-[2rem] border border-dashed border-ink/20 bg-white/35 p-8"><p className="text-xs font-bold uppercase tracking-[0.2em] text-pine">No real records yet</p><h2 className="mt-3 text-2xl font-black tracking-[-0.05em] text-ink">{role === "BuildingStaff" ? "No properties assigned" : "Start with your first property"}</h2><p className="mt-3 max-w-lg text-sm leading-6 text-ink/55">{role === "BuildingStaff" ? "An Admin can assign properties to your account. This view never shows unassigned properties." : "Use the setup editor below to configure floors and units. Demo data is never mixed into this workspace."}</p></div>; }
function CenteredState({ label }: { label: string }) { return <main className="flex min-h-screen items-center justify-center bg-sand px-6 text-sm font-bold text-pine">{label}</main>; }
function splitNames(value: string) { return value.split(",").map((name) => name.trim()).filter(Boolean); }
function makeKey() { return `${Date.now()}-${Math.random().toString(36).slice(2)}`; }
function todayInput() { return new Date().toISOString().slice(0, 10); }
function currentMonthInput() { return new Date().toISOString().slice(0, 7); }
function formatDate(value: string) { return new Intl.DateTimeFormat("en", { dateStyle: "medium" }).format(new Date(`${value}T00:00:00`)); }
function money(value: number) { return value.toFixed(2); }
function toChargeDraft(setting: ChargeConfiguration): ChargeDraft { return { key: setting.id || makeKey(), chargeType: setting.chargeType, mode: setting.mode, billingMonth: setting.billingMonth.slice(0, 7), amount: setting.amount === null ? "" : String(setting.amount), customLabel: setting.customLabel ?? "" }; }
function getErrorMessage(caught: unknown, fallback: string) { return caught instanceof ApiError ? caught.message : fallback; }
